#!/usr/bin/env python3
"""Check profile pins, declared page proofs and byte-identical public sources.

--update refreshes generated pins and copies; neither mode certifies a build.
Run check.py before publishing. The standalone Lean sources do not need Python.
"""
import argparse
import hashlib
from html.parser import HTMLParser
import json
from pathlib import Path
import re
import shutil
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent.parent
PUBLIC = ROOT / 'website/dist/formal/lean'
sys.path.insert(0, str(ROOT / 'model'))
from validator import load_profile


def quoted(value):
    return json.dumps(value, ensure_ascii=False)


def at(schema, *fields):
    node = schema
    for field in fields:
        node = node['properties'][field]
    return node


def profile_pins():
    lines = ['import MidnightExpress.Validation', '',
        '/- Generated by publish.py from verified installed bundle bytes and lock.json.',
        '   Pins the modeled release; does not prove bundle loading or wire decoding. -/',
        'namespace MidnightExpress.ProfilePins', '']
    roles = {'dealer': '.dealer', 'payment-adapter': '.paymentAdapter', 'human-approver': '.humanApprover'}
    schemas = {}
    for constructor, name in [('rfq', 'rfq.v0.2'), ('invoice', 'invoice.v0.2'), ('agent', 'agent.v0.2')]:
        bundle, contract = load_profile(name)
        schema = bundle['schemaObject']; schemas[constructor] = schema
        for method, value in [('name',at(schema,'mpeprofile')['const']),
                              ('eventType',at(schema,'type')['const']),
                              ('dataSchema',at(schema,'dataschema')['const']), ('contract',contract)]:
            lines.append(f'example : Profile.{constructor}.{method} = {quoted(value)} := rfl')
        lines.append(f'example : Profile.{constructor}.role = {roles[bundle["role"]]} := rfl')
        for method, field in [('specversion','specversion'),('contentType','datacontenttype')]:
            value = at(schema,field)['const']
            lines += [f'example (e : Envelope) (h : e.Matches .{constructor}) : e.{method} = {quoted(value)} := by',
                      '  rcases h with ⟨hSpec, hContent, hType, hSchema, hProfile, hContract⟩',
                      '  assumption']
    q, i, a = schemas['rfq'], schemas['invoice'], schemas['agent']
    patterns = []
    def visit(node):
        if isinstance(node,dict):
            if 'coefficient' in node.get('properties',{}):patterns.append(node['properties']['coefficient']['pattern'])
            for item in node.values():visit(item)
        elif isinstance(node,list):
            for item in node:visit(item)
    for schema in schemas.values():visit(schema)
    limits=[]
    for pattern in patterns:
        m=re.search(r'\{0,(\d+)\}',pattern)
        expected = '^[1-9][0-9]{0,' + (m.group(1) if m else '') + '}(?![' + chr(92) + 's' + chr(92) + 'S])'
        if not m or pattern != expected:
            raise ValueError('Unsupported decimal grammar in installed schema: '+pattern)
        limits.append(10**(int(m.group(1))+1)-1)
    if not limits or len(set(limits))!=1:raise ValueError('Decimal bounds disagree across pinned profiles')
    lines += [f'example : maxCoefficient = {limits[0]} := rfl', '']
    def const(schema,*path):return at(schema,*path)['const']
    # Singleton tags are part of the typed interpretation, not a verified decoder.
    expected = [(q,('data','currency'),'iso4217:USD'),(q,('data','quoteKind'),'Firm'),
                (q,('data','settlement'),'OffchainCoordinationOnly'),
                (q,('data','price','kind'),'AbsolutePerUnit'),(q,('data','price','fees'),'None'),
                (i,('data','currency'),'iso4217:USD'),(a,('data','proposal','environment'),'Sandbox')]
    for schema,path,value in expected:
        if const(schema,*path)!=value:raise ValueError('Unsupported typed singleton meaning at '+'.'.join(path))
    for schema,path,decoder,value in [(q,('data','currency'),'decodeCurrency','.usd'),
                                     (q,('data','quantity','unit'),'decodeUnit','.share'),
                                     (a,('data','proposal','budget','unit'),'decodeUnit','.step'),
                                     (a,('data','proposal','operation'),'decodeOperation','.writeReport')]:
        lines.append(f'example : {decoder} {quoted(const(schema,*path))} = some {value} := by decide')
    def gate_pin(tag, record, fields):
        for expression,value in fields:
            rhs=quoted(value) if isinstance(value,str) else str(value)
            lines.extend([f'example (c : Context) (e : Envelope) ({record}) (h : {tag} c e {record.split()[0]} = true) :',
                          f'    {expression} = {rhs} := by',
                          f'  have valid := ({tag}_iff c e {record.split()[0]}).mp h',
                          '  cases valid', '  simp_all [Decimal.ValidAt]', ''])
    gate_pin('rfqCheck','q : RFQ',[("q.price.baseQuantity",int(const(q,'data','price','baseQuantity'))),
         ('q.terms.quantity.value.scale',const(q,'data','quantity','scale')),
         ('q.price.value.scale',const(q,'data','price','value','scale')),
         ('q.cash.scale',const(q,'data','cash','scale'))])
    gate_pin('invoiceCheck','i : Invoice',[("i.rail",const(i,'data','rail')),
         ('i.amount.scale',const(i,'data','amount','scale')),('i.terms.payable.scale',const(i,'data','payable','scale'))])
    gate_pin('approvalCheck','a : Approval',[("a.authorityDomain",const(a,'data','authorityDomain')),
         ('a.budgetWindow',const(a,'data','budgetWindow')),('a.maxEffects',const(a,'data','maxEffects')),
         ('a.proposal.budget.value.scale',const(a,'data','proposal','budget','scale'))])
    lines += ['end MidnightExpress.ProfilePins', '']
    return '\n'.join(lines)


class ProofNames(HTMLParser):
    def __init__(self):
        super().__init__();self.names=[]
    def handle_starttag(self,tag,attrs):
        value=dict(attrs).get('data-proof')
        if value:self.names.extend(value.split())


def page_proofs():
    parser=ProofNames();parser.feed((ROOT/'website/dist/specification.html').read_text())
    if not parser.names:raise ValueError('Specification page must explicitly declare data-proof names')
    declarations=set()
    for p in (HERE/'MidnightExpress').glob('*.lean'):
        declarations.update(re.findall(r'(?m)^\s*(?:theorem|def|structure|inductive)\s+([A-Za-z][\w.\u003f]*)',p.read_text()))
    missing=sorted(set(parser.names)-declarations)
    if missing:raise ValueError('Page cites missing Lean declarations: '+', '.join(missing))


def sources():
    selected=[]
    for path in HERE.rglob('*'):
        if not path.is_file() or any(part in {'.lake','__pycache__'} for part in path.relative_to(HERE).parts):
            continue
        if path.suffix in {'.lean','.py','.json','.md'} or path.name=='lean-toolchain':
            selected.append(path)
    return sorted(selected)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    mode=parser.add_mutually_exclusive_group(required=True);mode.add_argument('--update',action='store_true');mode.add_argument('--check',action='store_true')
    args=parser.parse_args()
    pin=HERE/'MidnightExpress/ProfilePins.lean';expected=profile_pins()
    if args.update:pin.write_text(expected)
    elif not pin.exists() or pin.read_text()!=expected:raise ValueError('ProfilePins.lean drift: review changes and run publish.py --update')
    page_proofs()
    selected=sources()
    manifest={'toolchain':(HERE/'lean-toolchain').read_text().strip(),
      'boundary':'Typed validation and structural sequential journal; wire parsing, cryptography, external provenance, runtime refinement and durable effects need separate evidence',
      'files':[{'path':str(p.relative_to(HERE)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in selected]}
    data=(json.dumps(manifest,indent=2)+'\n').encode()
    if args.update:
        PUBLIC.mkdir(parents=True,exist_ok=True)
        for p in selected:
            target=PUBLIC/p.relative_to(HERE);target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,target)
        allowed={str(p.relative_to(HERE)) for p in selected}|{'source-manifest.json'}
        for p in PUBLIC.rglob('*'):
            if p.is_file() and str(p.relative_to(PUBLIC)) not in allowed:p.unlink()
        (PUBLIC/'source-manifest.json').write_bytes(data)
    else:
        for p in selected:
            target=PUBLIC/p.relative_to(HERE)
            if not target.exists() or target.read_bytes()!=p.read_bytes():raise ValueError('Public source drift: '+str(target.relative_to(ROOT)))
        if (PUBLIC/'source-manifest.json').read_bytes()!=data:raise ValueError('Public source manifest drift')
        if {str(p.relative_to(PUBLIC)) for p in PUBLIC.rglob('*') if p.is_file()}!={f['path'] for f in manifest['files']}|{'source-manifest.json'}:raise ValueError('Unexpected public source files')
    print('PASS profile pins, page declaration references and public source bytes')


if __name__=='__main__':
    try:main()
    except (ValueError,KeyError,OSError) as err:raise SystemExit(str(err))
